+      final result = await _local.createFileExclusive(path);
+      if (result.isErr) {
+        // ...and releases in the window: strip the flag, keep the
+        // code - the hostile platform's mapping drift, constructed.
+        final error = result.errorOrNull!;
+        await _local.remove(path);
+        return Err(
+          FileError(
+            error.code,
+            error.message,
+            path: error.path,
+            cause: error.cause,
+            pathExistsAtFailure: false,
+          ),
+        );
+      }
+      return result;
+    }
+    return _local.createFileExclusive(path);
+  }
+}
+
 /// An exclusive-create backend whose lock claim is refused by the fs, not
 /// by an occupant. The delegate's missing lock path makes the distinction
 /// observable to the coordinator's subsequent fileInfo probe.

