FileError _toFileError(Object error, String path) {
  if (error is FileError) return error;
  if (error is PathExistsException) {
    return FileError(
      // Occupancy is a CODED outcome, not unknown (issue #2355): the
      // manifest-lock coordinator reads the code to retry a rival's
      // release-in-window instead of surfacing it as an fs failure.
      FileErrorCode.exists,
      '${error.message}${_osErrorDetail(error.osError)}',
      path: path,
      cause: error,
      pathExistsAtFailure: true,
    );
  }
  if (error is PathNotFoundException) {
    return FileError(
      FileErrorCode.notFound,
      error.message,
      path: path,
      cause: error,
    );
  }
  if (error is FileSystemException) {
    return _fromFileSystemException(error, path);
  }
  return FileError(
    FileErrorCode.unknown,
    error.toString(),
    path: path,
    cause: error,
  );
}

/// The raw OS reason a [FileSystemException] carries (issue #2248 AC1):
/// `error.message` alone is the generic engine text ("Cannot open file")
/// — EMFILE vs EACCES vs a sandbox/container revocation are
/// indistinguishable from it, which is exactly why the 2026-11-17
/// wedge's root cause could not be diagnosed from fa.log. The errno +
/// OS message ride every [FileError] this env produces.
String _osErrorDetail(OSError? osError) =>
    osError == null ? '' : ' (errno ${osError.errorCode}: ${osError.message})';

FileError _fromFileSystemException(FileSystemException error, String path) {
  final osError = error.osError;
  final detail = _osErrorDetail(osError);
  if (osError != null) {
    // EPERM / EACCES on POSIX; ERROR_ACCESS_DENIED (5) on Windows.
    if (osError.errorCode == 13 ||
        osError.errorCode == 1 ||
        osError.errorCode == 5) {
      return FileError(
        FileErrorCode.permissionDenied,
        '${error.message}$detail',
        path: path,
        cause: error,
      );
    }
    // ENOTDIR on POSIX.
    if (osError.errorCode == 20) {
      return FileError(
        FileErrorCode.notDirectory,
        '${error.message}$detail',
        path: path,
        cause: error,
      );
    }
    // EEXIST on POSIX (17); ERROR_ALREADY_EXISTS (183) on Windows.
    // Issue #2355: `File.create(exclusive: true)` on some platforms
    // throws the PLAIN FileSystemException (not PathExistsException),
    // and the unmapped variant lost pathExistsAtFailure — the manifest
    // lock coordinator then surfaced a rival's release-in-window as an
    // fs failure (hostile-leg errno 17 reds) instead of retrying.
    if (osError.errorCode == 17 || osError.errorCode == 183) {
      return FileError(
        FileErrorCode.exists,
        '${error.message}$detail',
        path: path,
        cause: error,
        pathExistsAtFailure: true,
      );
    }
  }
  return FileError(
    FileErrorCode.unknown,
    '${error.message}$detail',
    path: path,
    cause: error,
  );
}

