      // straggler window (ENOTEMPTY 39 escaped the seam). A longer
      // exponential ladder (7 tries, ~12.7s ceiling) still ends in the
      // printed abandon: a disposable systemTemp artifact must never
      // fail a green run, but a real straggler gets room to land.
      if (attempt >= 7) {
        print('teardown left ${dir.path} behind: $error');
        return;
      }
      await Future<void>.delayed(Duration(milliseconds: 50 << (attempt - 1)));
    }
  }
}

/// Ported from pi's `FileErrorCode` union.
enum FileErrorCode {
  /// The operation was aborted.
  aborted,

  /// The addressed path does not exist.
  notFound,

  /// The target path already exists (EEXIST / ERROR_ALREADY_EXISTS) —
  /// occupancy, not failure: exclusive-create locks read this as "the
  /// rival holds it" (issue #2266, #2355).
  exists,

  /// The operation was denied by the platform.
  permissionDenied,

  /// A path component that must be a directory is not one.
  notDirectory,

  /// The addressed path is a directory but a file was required.

